+ep_sync_host_v2::Code l2_cache::sync_host_quiescent() const {
+  using ep_sync_host_v2::Code;
+  if(!m_gpu->sync_host_write_enabled()||!ft_enabled()||m_config.m_cache_type!=SECTOR||
+     m_config.get_num_lines()!=256||m_config.get_assoc()!=8||m_config.get_line_sz()!=128||
+     m_config.m_mshr_type!=ASSOC||m_config.m_alloc_policy!=ON_MISS||m_config.m_write_policy!=WRITE_BACK||
+     m_ep_l2_payload.physical_slots()!=1168||m_ep_l2_payload.bank_service_limit()!=1||
+     m_config.m_ep_l2_descriptor_pool_size!=512||m_config.m_ep_l2_wad_entries!=128||
+     m_config.m_mshr_entries!=128||m_config.m_ep_l2_descriptor_per_line_cap!=32||
+     m_config.m_ep_l2_static_s64||m_config.m_ep_l2_wb_local_cap||m_config.m_ep_l2_tvd_fixed_entries||
+     m_config.m_ep_l2_diag_copy_free||m_config.m_ep_l2_diag_l2_data_free||
+     m_config.m_ep_l2_ideal_wb||m_config.m_ep_l2_ideal_meta||m_config.m_ep_l2_ideal_read_hit||
+     m_config.m_ep_l2_mq2||m_config.m_ep_l2_rg1)return Code::HOLD_DOMAIN;
+  // Postkernel untimed writes are not a qualified LIFE/ET measurement path.
+  if(m_tag_array->lifetime()||ep_et::enabled()||ep_l2_detach_diag::state.enabled)
+    return Code::HOLD_DOMAIN;
+  const char*pressure=std::getenv("EPL2_TAGPRESSURE_DIAG");
+  if(pressure&&*pressure&&std::strcmp(pressure,"0"))return Code::HOLD_DOMAIN;
+  if(m_ro||(m_tvd&&m_tvd->occupied()))return Code::HOLD_ALIAS_RO;
+  if(!ft_drained()||ep_l2_wad_occupancy()||mshr_entries_used()||
+     m_mshrs.descriptor_count_used()||!miss_queue_empty()||m_tvd_lookup||m_tvd_read||
+     m_ep_l2_payload.pending_operations()||m_ep_l2_payload.pending_sector_count()||
+     !sync_host_no_tickets())return Code::HOLD_PENDING;
+  // A supposedly drained NativeTag RESERVED is not repaired by host overwrite.
+  for(unsigned i=0;i<m_config.get_num_lines();++i){
+    auto*b=m_tag_array->get_block(i);if(b->is_reserved_line())return Code::HOLD_PENDING;
+    if(!b->is_invalid_line()){auto h=tag_payload_handle(i);
+      if(!m_ep_l2_payload.handle_live(h))return Code::HOLD_IDENTITY;
+      const auto&s=m_ep_l2_payload.inspect(h);
+      if(s.pins||s.pending_sector_mask.any())return Code::HOLD_PENDING;
+      if(s.owner!=b->m_block_addr||s.allocation_role!=ep_l2_payload_store::RESIDENT)return Code::HOLD_IDENTITY;
+    }
+  }
+  return Code::READY;
+}
+ep_sync_host_v2::Code l2_cache::sync_host_snapshot(new_addr_type address,ep_sync_host::Resident&r){
+  using ep_sync_host_v2::Code;
+  const auto owner=m_config.block_addr(address);unsigned index=m_config.get_num_lines();
+  const unsigned first=m_config.set_index(address)*m_config.get_assoc();
+  for(unsigned i=first;i<first+m_config.get_assoc();++i){auto*b=m_tag_array->get_block(i);
+    if(b->m_block_addr==owner&&b->is_valid_line()){index=i;break;}}
+  // No replacement probe and no silent fallback to clean-init for ownerMISS.
+  if(index==m_config.get_num_lines())return Code::HOLD_OWNER_MISS;
+  const auto h=tag_payload_handle(index);
+  if(!m_ep_l2_payload.handle_live(h))return Code::HOLD_IDENTITY;
+  const auto&slot=m_ep_l2_payload.inspect(h);auto*tag=static_cast<sector_cache_block*>(m_tag_array->get_block(index));
+  if(slot.owner!=owner||slot.allocation_role!=ep_l2_payload_store::RESIDENT||slot.pins||
+     slot.pending_sector_mask.any()||tag->is_reserved_line()||h.payload_id%4!=index%4)
+    return Code::HOLD_IDENTITY;
+  unsigned native_ready=0;
+  for(unsigned s=0;s<4;++s){auto status=tag->diagnostic_sector_state(s);
+    mem_access_sector_mask_t mask;mask.set(s);r.readable[s]=tag->is_readable(mask);
+    if((status==VALID||status==MODIFIED)&&r.readable[s])native_ready|=1u<<s;}
+  if(native_ready!=slot.ready_sector_mask.to_ulong())return Code::HOLD_IDENTITY;
+  r.owner=owner;r.tag_index=index;r.payload_id=h.payload_id;r.payload_generation=h.generation;
+  r.bank=index%4;r.live=true;r.resident=true;r.pins=0;r.pending=0;r.ready=native_ready;
+  r.dirty=tag->get_dirty_sector_mask().to_ulong();r.dirty_bytes=tag->get_dirty_byte_mask();
+  for(unsigned s=0;s<4;++s)r.version[s]=slot.versions[s];
+  const unsigned sector=(address>>5)&3;
+  if(!(r.ready&(1u<<sector))||!r.readable[sector])return Code::HOLD_PENDING;
+  const bool dirty=bool(r.dirty);
+  if((dirty&&slot.status!=ep_l2_payload_store::RESIDENT_DIRTY)||
+     (!dirty&&slot.status!=ep_l2_payload_store::RESIDENT_VALID))return Code::HOLD_IDENTITY;
+  return Code::READY;
+}
+ep_sync_host_v2::Code l2_cache::sync_host_prepare(uint64_t epoch,const std::vector<uint64_t>&addresses){
+  using ep_sync_host_v2::Code;auto c=sync_host_quiescent();if(c!=Code::READY)return c;
+  try{
+    // These allocating global assertions are preflight-only. Commit never
+    // re-runs ownership_consistent's std::set allocation after changing data.
+    if(!m_ep_l2_payload.ownership_consistent())return Code::HOLD_IDENTITY;
+    std::set<new_addr_type> owners;
+    for(unsigned i=0;i<m_config.get_num_lines();++i){auto*b=m_tag_array->get_block(i);
+      if(!b->is_invalid_line()&&!owners.insert(b->m_block_addr).second)return Code::HOLD_IDENTITY;}
+    if(!m_sync_host)m_sync_host.reset(new ep_sync_host_v2::State);
+    std::vector<ep_sync_host_v2::Plan> plans;plans.reserve(addresses.size());
+    for(auto a:addresses){ep_sync_host_v2::Plan p;p.address=a;
+      c=sync_host_snapshot(a,p.expected);if(c!=Code::READY){
+        fprintf(stderr,"EPL2HOSTWRITEV2|PREPARE_HOLD|epoch=%llu|address=%llx|reason=%s\n",(unsigned long long)epoch,(unsigned long long)a,ep_sync_host_v2::name(c));return c;}
+      plans.push_back(p);}
+    return m_sync_host->prepare(epoch,std::move(plans));
+  }catch(const std::bad_alloc&){return Code::HOLD_ALLOC;}
+}
+ep_sync_host_v2::Code l2_cache::sync_host_validate(){
+  using ep_sync_host_v2::Code;auto c=sync_host_quiescent();if(c!=Code::READY)return c;
+  if(!m_sync_host)return Code::HOLD_COMMAND;
+  for(const auto&p:m_sync_host->plans()){ep_sync_host::Resident r;c=sync_host_snapshot(p.address,r);
+    if(c!=Code::READY||!(r==p.expected))return Code::HOLD_IDENTITY;}
+  return Code::READY;
+}
+void l2_cache::sync_host_cancel_prepare(){if(m_sync_host)m_sync_host->cancel_prepare();}
+void l2_cache::sync_host_publish(){assert(m_sync_host);m_sync_host->publish();}
+void l2_cache::sync_host_finish(){assert(m_sync_host);m_sync_host->finish();}
+ep_sync_host_v2::Code l2_cache::sync_host_commit(new_addr_type address,unsigned time){
+  using ep_sync_host_v2::Code;
+  if(!m_sync_host||!m_sync_host->published())return Code::HOLD_COMMAND;
+  auto*p=m_sync_host->plan(address);if(!p)return Code::HOLD_COMMAND;
+  if(p->committed)return Code::ALREADY;
+  ep_sync_host::Resident r;auto c=sync_host_snapshot(address,r);
+  if(c!=Code::READY||!(r==p->expected))return Code::HOLD_IDENTITY;
+  const unsigned sector=(address>>5)&3;const auto b=m_sync_host->backing(address);
+  if(!b.epoch||(b.value&ep_sync_host::host_namespace)==0)return Code::HOLD_IDENTITY;
+  ep_l2_life::untimed_scope untimed;
+  m_tag_array->sync_host_full_sector(r.tag_index,sector,time);
+  const ep_l2::PayloadHandle h(r.payload_id,r.payload_generation);
+  auto&slot=m_ep_l2_payload.inspect_mutable(h);slot.versions[sector]=b.value;
+  slot.status=m_tag_array->block_is_modified(r.tag_index)?ep_l2_payload_store::RESIDENT_DIRTY:
+      ep_l2_payload_store::RESIDENT_VALID;
+  // Snapshot ready/pending/handle are preserved; modified byte mask is native.
+  ep_sync_host::Resident after;c=sync_host_snapshot(address,after);assert(c==Code::READY);
+  assert(after.owner==r.owner&&after.tag_index==r.tag_index&&after.payload_id==r.payload_id&&
+      after.payload_generation==r.payload_generation&&after.ready==r.ready&&after.pending==r.pending);
+  // Owner/handle/role unchanged; no allocating whole-pool assertion here.
+  assert(slot.allocation_role==ep_l2_payload_store::RESIDENT);
+  m_sync_host->committed(address,after);
+  return Code::READY;
+}
+void l2_cache::sync_host_capture_wb(mem_fetch*mf,const std::array<unsigned long long,4>&expected){
+  if(!m_sync_host)return;std::array<uint64_t,4>v{};for(unsigned s=0;s<4;++s)v[s]=expected[s];
+  m_sync_host->capture_wb(reinterpret_cast<uintptr_t>(mf),mf->get_request_uid(),m_config.block_addr(mf->get_addr()),
+      mf->get_access_sector_mask().to_ulong(),mf->get_ep_l2_payload_id(),mf->get_ep_l2_payload_generation(),v);
+}
+ep_sync_host_v2::Replay l2_cache::sync_host_preview_fill(mem_fetch*mf,ep_l2::PayloadHandle h){
+  ep_sync_host_v2::Replay r;if(!m_sync_host)return r;
+  const auto&slot=m_ep_l2_payload.inspect(h);for(unsigned s=0;s<4;++s)r.values[s]=slot.versions[s];
+  r.mask=m_sync_host->replay_fill(reinterpret_cast<uintptr_t>(mf),mf->get_request_uid(),m_config.block_addr(mf->get_addr()),
+      mf->get_access_sector_mask().to_ulong(),h.payload_id,h.generation,r.values);return r;
+}
+void l2_cache::sync_host_commit_fill(mem_fetch*mf,ep_l2::PayloadHandle h,const ep_sync_host_v2::Replay&r){
+  if(!r.mask)return;auto&slot=m_ep_l2_payload.inspect_mutable(h);
+  for(unsigned s=0;s<4;++s)if(r.mask&(1u<<s))slot.versions[s]=r.values[s];
+  m_sync_host->retire_read(reinterpret_cast<uintptr_t>(mf));
+}
+void l2_cache::sync_host_validate_wb(mem_fetch*mf){
+  if(!m_sync_host)return;assert(mf->has_ft_wb_data());std::array<uint64_t,4>v{};
+  for(unsigned s=0;s<4;++s)v[s]=mf->get_ft_wb_data()[s];
+  m_sync_host->validate_wb(reinterpret_cast<uintptr_t>(mf),mf->get_request_uid(),m_config.block_addr(mf->get_addr()),
+      mf->get_access_sector_mask().to_ulong(),mf->get_ep_l2_payload_id(),mf->get_ep_l2_payload_generation(),v);
+}
+void l2_cache::sync_host_wb_done(mem_fetch*mf){
+  if(!m_sync_host)return;assert(mf->has_ft_wb_data());std::array<uint64_t,4>v{};
+  for(unsigned s=0;s<4;++s)v[s]=mf->get_ft_wb_data()[s];
+  m_sync_host->wb_done(reinterpret_cast<uintptr_t>(mf),mf->get_request_uid(),m_config.block_addr(mf->get_addr()),
+      mf->get_access_sector_mask().to_ulong(),mf->get_ep_l2_payload_id(),mf->get_ep_l2_payload_generation(),v);
+}
