+#pragma once
+// New private protocol candidate. No production call sites are connected yet.
+// GPU Source78 symbols are uint32 UID + 1 (<=2^32); initial-host symbol is0.
+#include <array>
+#include <bitset>
+#include <cstdint>
+#include <limits>
+#include <map>
+#include <stdexcept>
