+constexpr std::uint64_t host_namespace=std::uint64_t(1)<<63;
+constexpr std::uint64_t max_gpu_symbol=std::uint64_t(1)<<32;
+enum class Result { READY, APPLIED, ALREADY_APPLIED, BAD_EXTENT, UNSUPPORTED_RO,
+  NOT_QUIESCENT, UNSAFE_ALIAS, NOT_RESIDENT, OWNER_MISS, NEEDS_TIMED_MAINTENANCE,
+  PENDING_OR_PINNED, SECTOR_NOT_READY, BAD_IDENTITY, STALE_HOST_COMMAND,
+  STALE_BACKING_EPOCH, BAD_SYMBOL, LEDGER_BOUND };
