+ std::uint64_t owner=0,payload_generation=0;
+ unsigned tag_index=0,payload_id=0,bank=0;
+ bool live=true,resident=true;
+ unsigned pins=0;
+ std::uint8_t ready=0,dirty=0,pending=0;
+ std::bitset<128> dirty_bytes;
+ std::array<std::uint64_t,4> version{{0,0,0,0}};
+ std::array<bool,4> readable{{true,true,true,true}};
+ bool operator==(const Resident&x)const{return owner==x.owner&&payload_generation==x.payload_generation&&tag_index==x.tag_index&&payload_id==x.payload_id&&bank==x.bank&&live==x.live&&resident==x.resident&&pins==x.pins&&ready==x.ready&&dirty==x.dirty&&pending==x.pending&&dirty_bytes==x.dirty_bytes&&version==x.version&&readable==x.readable;}
+};
+struct Gates {
+ unsigned active_tag_lines=256,physical_payload_slots=1168;
+ bool ft=true,sector_cache=true,ro=false;
+ bool subpartition_drained=true,cache_drained=true,wad_empty=true,mshr_empty=true,
+  descriptors_empty=true,missqueue_empty=true,payload_ops_empty=true,
+  tvd_lookup_idle=true,tvd_read_idle=true,no_tvd_alias=true;
+};
+inline Result preview(const Resident&r,const Gates&g,std::uint64_t address,unsigned count){
+ if(count!=32 || (address&31) || address>std::numeric_limits<std::uint64_t>::max()-31)return Result::BAD_EXTENT;
+ if(g.ro)return Result::UNSUPPORTED_RO;
+ if(!g.ft||!g.sector_cache||!g.subpartition_drained||!g.cache_drained||!g.wad_empty||!g.mshr_empty||!g.descriptors_empty||!g.missqueue_empty||!g.payload_ops_empty||!g.tvd_lookup_idle||!g.tvd_read_idle)return Result::NOT_QUIESCENT;
+ if(!g.no_tvd_alias)return Result::UNSAFE_ALIAS;
+ if(!r.live||!r.resident)return Result::NOT_RESIDENT;
+ if(r.owner!=(address&~std::uint64_t(127)))return r.dirty?Result::NEEDS_TIMED_MAINTENANCE:Result::OWNER_MISS;
+ if(r.pins||r.pending)return Result::PENDING_OR_PINNED;
+ if(!r.payload_generation||r.tag_index>=g.active_tag_lines||r.payload_id>=g.physical_payload_slots||r.bank!=r.tag_index%4||r.bank!=r.payload_id%4)return Result::BAD_IDENTITY;
