+ if(!(r.ready&(1u<<s))||!r.readable[s])return Result::SECTOR_NOT_READY;
+ return Result::READY;
+}
+struct Backing {std::uint64_t value=0,host_epoch=0;};
+class Ledger {
+ std::map<std::uint64_t,Backing> memory;
+ std::uint64_t active=0,finished=0;
+ std::size_t bound;
+ public:
+ explicit Ledger(std::size_t maximum_tracked_sectors):bound(maximum_tracked_sectors){}
+ // Bound is an explicit correctness-shadow implementation limit, not GPU SRAM.
+ Result begin(std::uint64_t command_epoch){
+  if(!command_epoch||command_epoch>=host_namespace||active||command_epoch<=finished)return Result::STALE_HOST_COMMAND;
+  active=command_epoch;return Result::READY;
+ }
+ Result finish(std::uint64_t epoch){if(active!=epoch||!epoch)return Result::STALE_HOST_COMMAND;finished=epoch;active=0;return Result::APPLIED;}
+ std::size_t entries()const{return memory.size();}
+ std::uint64_t active_epoch()const{return active;}
+ Backing backing(std::uint64_t address)const{auto i=memory.find(address&~std::uint64_t(31));return i==memory.end()?Backing{}:i->second;}
+ Result host_sector(Resident&r,const Gates&g,std::uint64_t address,unsigned count,std::uint64_t command_epoch){
+  const Result p=preview(r,g,address,count);if(p!=Result::READY)return p;
+  if(!active||active!=command_epoch)return Result::STALE_HOST_COMMAND;
+  const auto key=address&~std::uint64_t(31);const unsigned s=(address>>5)&3;
+  const auto prior=backing(key);const auto symbol=host_namespace|command_epoch;
+  if(prior.host_epoch>command_epoch)return Result::STALE_HOST_COMMAND;
+  if(prior.host_epoch==command_epoch){
+   return prior.value==symbol&&r.version[s]==symbol&&!(r.dirty&(1u<<s))?Result::ALREADY_APPLIED:Result::STALE_HOST_COMMAND;
+  }
+  if(!memory.count(key)&&memory.size()==bound)return Result::LEDGER_BOUND;
+  // Allocate shadow storage first: allocation failure leaves physical state unchanged.
+  auto i=memory.emplace(key,prior).first;
+  // In the production bridge these operations require a freshly verified exact
+  // Tag+payload generation snapshot, no scheduler yield between validate/commit.
+  i->second={symbol,command_epoch};r.version[s]=symbol;r.ready|=1u<<s;
+  r.dirty&=std::uint8_t(~(1u<<s));r.readable[s]=true;
+  for(unsigned b=32*s;b<32*(s+1);++b)r.dirty_bytes.reset(b);
+  return Result::APPLIED;
+ }
+ // Called only at actual lower WB set_done, with the host epoch captured at
+ // creation. This is a shadow-data completion, never a fabricated GPU request.
+ Result wb_done(std::uint64_t address,std::uint64_t observed_host_epoch,std::uint64_t gpu_symbol){
+  if(active)return Result::NOT_QUIESCENT;
+  if(!gpu_symbol||gpu_symbol>max_gpu_symbol)return Result::BAD_SYMBOL;
+  const auto key=address&~std::uint64_t(31);auto prior=backing(key);
+  if(prior.host_epoch!=observed_host_epoch)return Result::STALE_BACKING_EPOCH;
+  if(!memory.count(key)&&memory.size()==bound)return Result::LEDGER_BOUND;
+  memory[key]={gpu_symbol,prior.host_epoch};return Result::APPLIED;
+ }
+ Result lower_fill(std::uint64_t address,std::uint64_t observed_host_epoch,std::uint64_t&value)const{
+  const auto b=backing(address);if(active||b.host_epoch!=observed_host_epoch)return Result::STALE_BACKING_EPOCH;
+  value=b.value;return Result::APPLIED;
+ }
+};
