+#pragma once
+// PrivateV2: model/source adapters require an independently rebuilt producer.
+#include "ep-l2-sync-host-write-base.h"
+#include <algorithm>
+#include <cstdlib>
+#include <cstring>
+#include <memory>
+#include <vector>
+namespace ep_sync_host_v2 {
+using ep_sync_host::Resident;
+constexpr std::size_t sectors_per_cache_bound=4096;
+constexpr std::size_t command_sector_bound=65536;
+enum class Code { DONE, MORE, WAIT_DRAIN, READY, ALREADY, DISABLED, HOLD_DOMAIN,
+ HOLD_IDENTITY, HOLD_PENDING, HOLD_ALIAS_RO, HOLD_OWNER_MISS,
+ HOLD_SHADOW_BOUND, HOLD_ALLOC, HOLD_COMMAND, HOLD_UNEXPECTED };
+inline bool hold(Code c){return c>=Code::HOLD_DOMAIN;}
+inline const char* name(Code c){switch(c){
+#define HW_NAME(x) case Code::x:return #x
+ HW_NAME(DONE);HW_NAME(MORE);HW_NAME(WAIT_DRAIN);HW_NAME(READY);HW_NAME(ALREADY);HW_NAME(DISABLED);
+ HW_NAME(HOLD_DOMAIN);HW_NAME(HOLD_IDENTITY);HW_NAME(HOLD_PENDING);HW_NAME(HOLD_ALIAS_RO);
+ HW_NAME(HOLD_OWNER_MISS);HW_NAME(HOLD_SHADOW_BOUND);HW_NAME(HOLD_ALLOC);
+ HW_NAME(HOLD_COMMAND);HW_NAME(HOLD_UNEXPECTED);
+#undef HW_NAME
+ }return "UNKNOWN";}
+inline void require(bool ok,const char *m){if(!ok)throw std::logic_error(m);}
+struct Backing {std::uint64_t value=0,epoch=0;};
+struct Plan {std::uint64_t address=0;Resident expected;bool committed=false;};
+struct Replay {unsigned mask=0;std::array<std::uint64_t,4> values;};
+struct Ticket {
+ bool live;std::uintptr_t key;unsigned uid,payload_id,payload_generation;
+ std::uint64_t owner;unsigned mask;
+ std::array<std::uint64_t,4> epochs,expected;
+};
+class State {
+ std::map<std::uint64_t,Backing> ledger;
+ struct Prepared {std::uint64_t epoch;std::map<std::uint64_t,Backing> next;
+  std::vector<Plan> plans;bool published=false;};
+ std::unique_ptr<Prepared> prepared;
+ std::array<Ticket,512> reads;
+ std::array<Ticket,128> wbs;
+ unsigned read_count=0,wb_count=0;
+ std::uint64_t last_epoch=0;
+ template<std::size_t N> Ticket* find(std::array<Ticket,N>&a,std::uintptr_t key){
+  for(auto &t:a)if(t.live&&t.key==key)return &t;return nullptr;}
+ template<std::size_t N> void capture(std::array<Ticket,N>&a,unsigned&count,
+   std::uintptr_t key,unsigned uid,std::uint64_t owner,unsigned sectors,
+   unsigned payload_id,unsigned generation,const std::array<std::uint64_t,4>&values){
+  unsigned known=0;for(unsigned s=0;s<4;++s)if((sectors&(1u<<s))&&ledger.count(owner+32*s))known|=1u<<s;
+  if(!known)return;require(!prepared,"GPU transfer while host command active");
+  require(!find(a,key),"duplicate host-shadow packet ticket");
+  Ticket value{};value.live=true;value.key=key;value.uid=uid;value.owner=owner;
+  value.mask=known;value.payload_id=payload_id;value.payload_generation=generation;
+  value.expected=values;
+  for(unsigned s=0;s<4;++s)if(known&(1u<<s))value.epochs[s]=ledger.at(owner+32*s).epoch;
+  // Fixed capacity follows D512/read and WAD128/WB; no allocation at issue.
+  for(auto&t:a)if(!t.live){t=value;++count;return;}
+  throw std::logic_error("host-shadow ticket bound invariant");
+ }
+ void identity(const Ticket&t,unsigned uid,std::uint64_t owner,unsigned payload_id,unsigned gen)const{
+  require(t.uid==uid&&t.owner==owner&&t.payload_id==payload_id&&t.payload_generation==gen,
