+  for(unsigned s=0;s<4;++s)if(t.mask&(1u<<s)){
+   auto i=ledger.find(owner+32*s);require(i!=ledger.end()&&i->second.epoch==t.epochs[s],"host-shadow stale host epoch");
+  }
+ }
+ public:
+ State(){for(auto&t:reads)t.live=false;for(auto&t:wbs)t.live=false;}
+ bool no_tickets()const{return !read_count&&!wb_count;}
+ bool busy()const{return bool(prepared);}
+ bool has_symbols()const{return !ledger.empty();}
+ std::size_t entries()const{return ledger.size();}
+ Backing backing(std::uint64_t address)const{auto i=ledger.find(address&~std::uint64_t(31));return i==ledger.end()?Backing{}:i->second;}
+ Code prepare(std::uint64_t epoch,std::vector<Plan> plans){
+  if(prepared||!no_tickets()||!epoch||epoch>=ep_sync_host::host_namespace||epoch<=last_epoch)return Code::HOLD_COMMAND;
+  try {
+   std::unique_ptr<Prepared> p(new Prepared);p->epoch=epoch;p->next=ledger;p->plans=std::move(plans);
+   std::sort(p->plans.begin(),p->plans.end(),[](const Plan&a,const Plan&b){return a.address<b.address;});
+   for(std::size_t n=0;n<p->plans.size();++n){auto &r=p->plans[n];
+    if((r.address&31)||(n&&r.address==p->plans[n-1].address))return Code::HOLD_DOMAIN;
+    auto i=p->next.find(r.address);if(i!=p->next.end()&&i->second.epoch>=epoch)return Code::HOLD_COMMAND;
+    if(i==p->next.end()&&p->next.size()==sectors_per_cache_bound)return Code::HOLD_SHADOW_BOUND;
