+   }
+   prepared=std::move(p);return Code::READY;
+  }catch(const std::bad_alloc&){return Code::HOLD_ALLOC;}
+ }
+ void cancel_prepare(){require(!prepared||!prepared->published,"cannot roll back published host command");prepared.reset();}
+ void publish(){require(prepared&&!prepared->published&&no_tickets(),"bad host publish");ledger.swap(prepared->next);prepared->published=true;}
+ Plan* plan(std::uint64_t address){
+  if(!prepared)return nullptr;auto &a=prepared->plans;
+  auto i=std::lower_bound(a.begin(),a.end(),address,[](const Plan&p,std::uint64_t x){return p.address<x;});
+  return i!=a.end()&&i->address==address?&*i:nullptr;
+ }
+ const std::vector<Plan>&plans()const{require(bool(prepared),"no host plan");return prepared->plans;}
+ bool published()const{return prepared&&prepared->published;}
+ void committed(std::uint64_t address,const Resident&after){
+  require(published(),"host not published");Plan*p=plan(address);require(p&&!p->committed,"duplicate host commit");p->committed=true;
