+  const auto owner=address&~std::uint64_t(127);
+  for(auto &n:prepared->plans)if((n.address&~std::uint64_t(127))==owner)n.expected=after;
+ }
+ void finish(){require(prepared&&prepared->published&&no_tickets(),"host finish without published command");
