+class Command {
+ public:enum class Phase{IDLE,WAIT,COMMIT,COMPLETE,HOLD};
+ private:Phase phase_=Phase::IDLE;
+ public:std::uint64_t id=0,address=0;std::size_t bytes=0,cursor=0;Code failure=Code::READY;
+ std::vector<unsigned> destinations;
+ Phase phase()const{return phase_;}bool committing()const{return phase_==Phase::COMMIT;}
+ Code request(std::uint64_t next,std::uint64_t base,std::size_t count){
+  if(phase_!=Phase::IDLE&&next==id){if(base!=address||count!=bytes)return fail(Code::HOLD_COMMAND);return phase_==Phase::COMPLETE?Code::DONE:phase_==Phase::HOLD?failure:Code::MORE;}
+  if((phase_!=Phase::IDLE&&phase_!=Phase::COMPLETE)||next<=id)return fail(Code::HOLD_COMMAND);
+  if(!next||next>=ep_sync_host::host_namespace||(base&31)||(count&31)||count/32>command_sector_bound||
+     (count&&base>std::numeric_limits<std::uint64_t>::max()-(count-1)))return fail(Code::HOLD_DOMAIN);
+  id=next;address=base;bytes=count;cursor=0;destinations.clear();phase_=Phase::WAIT;return Code::MORE;
+ }
+ void begin_commit(){require(phase_==Phase::WAIT,"bad host command phase");phase_=Phase::COMMIT;}
+ void advance(){require(committing()&&cursor<bytes,"host cursor beyond extent");cursor+=32;}
+ void complete(){require(committing()&&cursor==bytes,"incomplete host byte extent");phase_=Phase::COMPLETE;}
+ Code fail(Code c){failure=c;phase_=Phase::HOLD;return c;}
+};
